--- index.html
+++ index.html
@@ -31,4 +31,30 @@
 <div class="overlay" id="overlay"><section class="panel"><div class="eyebrow" id="eyebrow">UNA SAGA DE HIELO Y CENIZA</div><h1 class="title" id="title">HIJOS DEL<span>INVIERNO</span></h1><p class="intro" id="intro">El bosque ha olvidado el sol. Las criaturas antiguas han despertado bajo la nieve. Empuña el hacha, resiste la noche y abre paso hacia el alba.</p><button class="button" id="startButton">COMENZAR LA SAGA</button><div class="subline" id="subline">A / D moverse · J atacar · Espacio esquivar · K desatar la furia</div></section></div>
 <div class="touch-ui"><div class="touch-group"><button class="touch-btn" data-key="left">◀<span>MOVER</span></button><button class="touch-btn" data-key="right">▶<span>MOVER</span></button><button class="touch-btn" data-key="dodge">↗<span>RODAR</span></button></div><div class="touch-group"><button class="touch-btn attack" data-key="rage">✦<span>FURIA</span></button><button class="touch-btn attack" data-key="attack">✧<span>HACHA</span></button></div></div>
 </main>
 <script>
+(()=>{
+'use strict';
+const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
+const W=960,H=540,FLOOR=438,worldW=1900;
+const ui={overlay:document.querySelector('#overlay'),start:document.querySelector('#startButton'),title:document.querySelector('#title'),intro:document.querySelector('#intro'),eyebrow:document.querySelector('#eyebrow'),subline:document.querySelector('#subline'),health:document.querySelector('#healthBar'),healthNum:document.querySelector('#healthNum'),rage:document.querySelector('#rageBar'),rageNum:document.querySelector('#rageNum'),wave:document.querySelector('#waveLabel'),objective:document.querySelector('#objective'),pause:document.querySelector('#pauseLabel')};
+let mode='menu',last=0,timer=0,camera=0,shake=0,flash=0,round=0,spawnTimer=0,transitionTimer=0,screenMessage='',messageTimer=0;
+let player,enemies=[],particles=[],bolts=[],snow=[],keys={},audio=null,muted=false;
+const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
+function initWorld(){player={x:270,y:FLOOR,vx:0,vy:0,w:40,h:89,hp:100,maxHp:100,rage:0,face:1,ground:true,attack:0,attackCd:0,combo:0,dodge:0,dodgeCd:0,invuln:0,hurt:0,anim:0};enemies=[];particles=[];bolts=[];snow=Array.from({length:105},()=>({x:Math.random()*W,y:Math.random()*H,z:rand(.35,1),v:rand(18,65)}));round=0;camera=0;spawnTimer=0;transitionTimer=0;}
+function startGame(){initWorld();mode='play';ui.overlay.classList.add('hidden');ui.pause.classList.remove('show');beginWave(1);if(!audio)startMusic();else if(audio.ctx.state==='suspended')audio.ctx.resume();}
+function beginWave(n){round=n;const count=n===1?3:n===2?4:1;for(let i=0;i<count;i++){const x=player.x+rand(310,660)*(Math.random()<.5?-1:1);enemies.push(makeEnemy(n===3?'wight':'draugr',clamp(x,90,worldW-80),n));}if(n===3)enemies[0].boss=true;ui.objective.textContent=n===3?'Derrota al guardián de escarcha':'Sobrevive a la emboscada';ui.wave.innerHTML=`${n===3?'GUARDIÁN FINAL':`OLEADA ${n} / 3`}<small>${n===3?'EL VIGÍA DEL ABISMO':'EL BOSQUE DESPIERTA'}</small>`;message(n===3?'EL VIGÍA DEL ABISMO':'OLEADA '+n,1.8);}
+function makeEnemy(type,x,wave){const boss=type==='wight';let hp=boss?390:wave===1?48:64;return{x,y:FLOOR,vx:0,vy:0,w:boss?76:40,h:boss?140:82,hp,maxHp:hp,face:-1,boss,attack:0,attackCd:rand(.6,1.7),wind:0,hurt:0,stun:0,anim:rand(0,6),ground:true,dead:false,leap:0};}
+function message(text,duration=1){screenMessage=text;messageTimer=duration;}
+function startMusic(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const ac=new AC(),master=ac.createGain();master.gain.value=.12;master.connect(ac.destination);const low=ac.createOscillator(),lowGain=ac.createGain();low.type='sine';low.frequency.value=55;lowGain.gain.value=.22;low.connect(lowGain).connect(master);low.start();const pad=ac.createOscillator(),pad2=ac.createOscillator(),pg=ac.createGain(),filter=ac.createBiquadFilter();pad.type='triangle';pad2.type='sine';pad.frequency.value=110;pad2.frequency.value=164.81;filter.type='lowpass';filter.frequency.value=430;pg.gain.value=.08;pad.connect(filter);pad2.connect(filter);filter.connect(pg).connect(master);pad.start();pad2.start();audio={ctx:ac,master,low,pad,pad2,pg,step:0,next:0};}catch(e){console.warn('Audio no disponible',e)}}
+function tone(freq,dur=.12,wave='sine',volume=.1){if(!audio||muted)return;const {ctx,master}=audio;const o=ctx.createOscillator(),g=ctx.createGain();o.type=wave;o.frequency.setValueAtTime(freq,ctx.currentTime);g.gain.setValueAtTime(volume,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+dur);o.connect(g).connect(master);o.start();o.stop(ctx.currentTime+dur);}
+function musicTick(){if(!audio||muted||audio.ctx.state!=='running')return;const now=audio.ctx.currentTime;if(now<audio.next)return;audio.next=now+1.35;const notes=[110,130.81,146.83,98,123.47,164.81,146.83,110];const f=notes[audio.step++%notes.length];audio.pad.frequency.setTargetAtTime(f,audio.ctx.currentTime,.25);audio.pad2.frequency.setTargetAtTime(f*1.5,audio.ctx.currentTime,.35);audio.low.frequency.setTargetAtTime(f/2,audio.ctx.currentTime,.4);if(Math.random()<.27)tone(f*2,.8,'sine',.018);}
+function setKey(code,on){keys[code]=on;if(on&&mode==='play'){if(code==='KeyJ'||code==='ArrowUp')attack();if(code==='Space')dodge();if(code==='KeyK')rageBurst();if(code==='KeyP'||code==='Escape')togglePause();}}
+window.addEventListener('keydown',e=>{if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.code==='KeyM'&&!e.repeat){muted=!muted;if(audio)audio.master.gain.setTargetAtTime(muted?0:.12,audio.ctx.currentTime,.1);}if(e.code==='Enter'&&mode!=='play')startGame();if(!e.repeat)setKey(e.code,true);});window.addEventListener('keyup',e=>{keys[e.code]=false});
+function togglePause(){if(mode==='play'){mode='pause';ui.pause.classList.add('show');if(audio)audio.master.gain.setTargetAtTime(.035,audio.ctx.currentTime,.15)}else if(mode==='pause'){mode='play';ui.pause.classList.remove('show');if(audio){audio.ctx.resume();audio.master.gain.setTargetAtTime(muted?0:.12,audio.ctx.currentTime,.15)}}}
+function attack(){if(player.attackCd>0||player.dodge>0)return;player.attack=.34;player.attackCd=.43;player.combo=(player.combo+1)%3;player.rage=Math.min(100,player.rage+4);tone(player.combo===2?118:160,.12,'triangle',.11);}
+function dodge(){if(player.dodgeCd>0||!player.ground)return;player.dodge=.43;player.dodgeCd=.88;player.invuln=.48;player.vx=player.face*490;player.vy=-48;for(let i=0;i<10;i++)particle(player.x,player.y-15,'#c8dbd4',rand(-100,100),rand(-100,30),.45);tone(250,.16,'sine',.06);}
+function rageBurst(){if(player.rage<100)return;player.rage=0;player.attack=.65;player.attackCd=.72;shake=18;flash=.25;tone(62,.65,'sawtooth',.16);for(let i=0;i<48;i++){const a=Math.random()*Math.PI*2,s=rand(80,360);particle(player.x,player.y-38,'#9be5df',Math.cos(a)*s,Math.sin(a)*s,.8)}for(const e of enemies){if(dist(player,e)<270){damageEnemy(e,95);e.stun=1.1}}message('FURIA DEL INVIERNO',.8);}
+function particle(x,y,color,vx,vy,life=.5,size=rand(2,5)){particles.push({x,y,color,vx,vy,life,max:life,size,gravity:rand(80,320)});}
+function hitPlayer(amount,from){if(player.invuln>0||mode!=='play')return;player.hp=Math.max(0,player.hp-amount);player.hurt=.25;player.invuln=.65;player.vx=(player.x<from.x?-1:1)*180;shake=8;flash=.12;tone(74,.2,'sawtooth',.09);for(let i=0;i<12;i++)particle(player.x,player.y-40,'#b65143',rand(-150,150),rand(-200,20),.5);if(player.hp<=0)endGame(false);}
+function damageEnemy(e,amount){if(e.dead)return;e.hp-=amount;e.hurt=.18;player.rage=Math.min(100,player.rage+(e.boss?5:10));shake=Math.max(shake,e.boss?9:4);for(let i=0;i<9;i++)particle(e.x,e.y-35,e.boss?'#83d8d1':'#d18b68',rand(-170,170),rand(-200,35),.5);tone(e.boss?88:120,.13,'square',.07);if(e.hp<=0){e.dead=true;for(let i=0;i<20;i++)particle(e.x,e.y-30,'#9acdc3',rand(-200,200),rand(-230,10),.85);if(e.boss){message('EL BOSQUE RESPIRA',1.8);setTimeout(()=>endGame(true),1600)}}}
+function endGame(win){mode=win?'win':'dead';ui.overlay.classList.remove('hidden');ui.eyebrow.textContent=win?'FIN DEL CAPÍTULO':'EL INVIERNO TE RECLAMA';ui.title.innerHTML=win?'EL ALBA<span>HA VUELTO</span>':'LA NOCHE<span>PREVALECE</span>';ui.intro.textContent=win?'El Vigía ha caído. Bajo el hielo, la tierra recuerda cómo florecer. Pero en el norte, una nueva canción ya comienza…':'La nieve cubre tus huellas. Aún hay calor en las brasas y otra oportunidad en el horizonte.';ui.start.textContent=win?'JUGAR DE NUEVO':'INTENTAR DE NUEVO';ui.subline.textContent='Pulsa el botón o Enter para volver al combate';}

