function endGame(win){mode=win?'win':'dead';ui.overlay.classList.remove('hidden');ui.eyebrow.textContent=win?'FIN DEL CAPÍTULO':'EL INVIERNO TE RECLAMA';ui.title.innerHTML=win?'EL ALBA<span>HA VUELTO</span>':'LA NOCHE<span>PREVALECE</span>';ui.intro.textContent=win?'El Vigía ha caído. Bajo el hielo, la tierra recuerda cómo florecer. Pero en el norte, una nueva canción ya comienza…':'La nieve cubre tus huellas. Aún hay calor en las brasas y otra oportunidad en el horizonte.';ui.start.textContent=win?'JUGAR DE NUEVO':'INTENTAR DE NUEVO';ui.subline.textContent='Pulsa el botón o Enter para volver al combate';}
function update(dt){timer+=dt;musicTick();if(mode!=='play'){updateAmbient(dt);return}messageTimer=Math.max(0,messageTimer-dt);shake=Math.max(0,shake-dt*28);flash=Math.max(0,flash-dt);player.attackCd=Math.max(0,player.attackCd-dt);player.attack=Math.max(0,player.attack-dt);player.dodgeCd=Math.max(0,player.dodgeCd-dt);player.dodge=Math.max(0,player.dodge-dt);player.invuln=Math.max(0,player.invuln-dt);player.hurt=Math.max(0,player.hurt-dt);player.anim+=dt*8;
let move=(keys.KeyA||keys.ArrowLeft?-1:0)+(keys.KeyD||keys.ArrowRight?1:0);if(player.dodge<=0){if(move){player.face=move;player.vx+=move*1450*dt;player.vx=clamp(player.vx,-270,270)}else player.vx*=Math.pow(.001,dt);if((keys.KeyW||keys.ArrowUp)&&player.ground)player.vy=-420;}player.x=clamp(player.x+player.vx*dt,35,worldW-35);player.y+=player.vy*dt;player.vy+=1100*dt;if(player.y>=FLOOR){player.y=FLOOR;player.vy=0;player.ground=true}else player.ground=false;if(player.attack>0&&player.attack<.22&&player.attack>.08){for(const e of enemies){if(!e.dead&&Math.abs(e.y-player.y)<100&&Math.abs(e.x-player.x)<(e.boss?150:115)&&Math.sign(e.x-player.x)===player.face&&!e.hitSwing){e.hitSwing=true;damageEnemy(e,e.boss?24:player.combo===2?39:28);e.vx=player.face*(e.boss?80:200)} }}if(player.attack<=0)for(const e of enemies)e.hitSwing=false;
for(const e of enemies){if(e.dead)continue;e.anim+=dt*(e.boss?4:6);e.hurt=Math.max(0,e.hurt-dt);e.stun=Math.max(0,e.stun-dt);e.attackCd-=dt;const dx=player.x-e.x,ad=Math.abs(dx);e.face=Math.sign(dx)||e.face;if(e.stun<=0&&e.wind<=0){if(ad>(e.boss?115:70)){e.vx+=e.face*(e.boss?350:520)*dt;e.vx=clamp(e.vx,-(e.boss?120:95),e.boss?120:95)}else{e.vx*=Math.pow(.002,dt);if(e.attackCd<=0){e.wind=e.boss?.72:.48;e.attackCd=e.boss?2.05:1.55}}}else e.vx*=Math.pow(.04,dt);e.x=clamp(e.x+e.vx*dt,25,worldW-25);if(e.wind>0){e.wind-=dt;if(e.wind<=0){e.attack=e.boss?.34:.24;e.leap=e.boss?220:130;}}if(e.attack>0){e.attack-=dt;if(e.attack<(e.boss?.19:.14)&&e.attack>0&&Math.abs(e.x-player.x)<e.leap&&player.ground)hitPlayer(e.boss?20:11,e)} }
enemies=enemies.filter(e=>!e.dead||particles.some(p=>Math.abs(p.x-e.x)<10));enemies=enemies.filter(e=>!e.dead);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=p.gravity*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);updateAmbient(dt);camera=clamp(player.x-W*.43,0,worldW-W);ui.health.style.width=(player.hp/player.maxHp*100)+'%';ui.healthNum.textContent=Math.ceil(player.hp);ui.rage.style.width=player.rage+'%';ui.rageNum.textContent=Math.floor(player.rage);if(round<3&&enemies.length===0){transitionTimer+=dt;if(transitionTimer>1.4){transitionTimer=0;beginWave(round+1)}}}
function updateAmbient(dt){for(const s of snow){s.y+=s.v*dt;s.x+=Math.sin(timer*1.1+s.z*8)*dt*13;if(s.y>H+4){s.y=-5;s.x=Math.random()*W}}}
function draw(){ctx.clearRect(0,0,W,H);drawSky();ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake/2,shake/2));ctx.save();ctx.translate(-camera,0);drawTerrain();for(const e of enemies)drawEnemy(e);drawPlayer();for(const p of particles)drawParticle(p);ctx.restore();ctx.restore();drawSnow();if(flash>0){ctx.fillStyle=`rgba(180,225,222,${flash*1.6})`;ctx.fillRect(0,0,W,H)}if(messageTimer>0){ctx.save();ctx.globalAlpha=Math.min(1,messageTimer*2);ctx.textAlign='center';ctx.fillStyle='#efe2c7';ctx.font='500 24px Cinzel,serif';ctx.letterSpacing='5px';ctx.shadowColor='#080c0e';ctx.shadowBlur=14;ctx.fillText(screenMessage,W/2,145);ctx.restore()}}
function drawSky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#101d27');g.addColorStop(.52,'#30434a');g.addColorStop(1,'#69716a');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);const glow=ctx.createRadialGradient(690,125,10,690,125,330);glow.addColorStop(0,'#9baf9c38');glow.addColorStop(1,'#9baf9c00');ctx.fillStyle=glow;ctx.fillRect(300,0,600,400);
// aurora ribbons
ctx.save();ctx.globalCompositeOperation='screen';for(let j=0;j<3;j++){ctx.beginPath();for(let x=-30;x<=W+30;x+=16){let y=106+j*22+Math.sin(x*.008+timer*.22+j)*24+Math.sin(x*.019-timer*.13)*9;if(x===-30)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.strokeStyle=`rgba(${100+j*12},${184+j*12},${164+j*15},${.055+j*.012})`;ctx.lineWidth=28-j*5;ctx.shadowColor='#83d6be';ctx.shadowBlur=28;ctx.stroke()}ctx.restore();
const layers=[{base:320,color:'#263b42',amp:55,scale:.006,off:camera*.08},{base:365,color:'#1b3036',amp:36,scale:.009,off:camera*.16},{base:403,color:'#19292d',amp:24,scale:.015,off:camera*.27}];for(const l of layers){ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<=W;x+=8)ctx.lineTo(x,l.base+Math.sin((x+l.off)*l.scale)*l.amp+Math.sin((x+l.off)*l.scale*2.7)*l.amp*.28);ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=l.color;ctx.fill()}ctx.fillStyle='#bdc7ba';ctx.globalAlpha=.35;ctx.beginPath();ctx.arc(754,112,25,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
// distant firs
for(let i=0;i<18;i++){const x=((i*89-camera*.19)%1120+1120)%1120-70;const h=60+(i*37%70);ctx.fillStyle=i%2?'#17282d':'#1c3033';ctx.beginPath();ctx.moveTo(x,394-h);ctx.lineTo(x-25,395);ctx.lineTo(x+28,395);ctx.closePath();ctx.fill();}}
function drawTerrain(){ctx.fillStyle='#172327';ctx.fillRect(0,FLOOR,worldW,H-FLOOR);const grad=ctx.createLinearGradient(0,FLOOR,0,H);grad.addColorStop(0,'#51605a');grad.addColorStop(.15,'#303b39');grad.addColorStop(1,'#172124');ctx.fillStyle=grad;ctx.fillRect(0,FLOOR,worldW,H-FLOOR);ctx.fillStyle='#d3d9cd';ctx.fillRect(0,FLOOR,worldW,3);ctx.globalAlpha=.35;ctx.fillStyle='#edf1e8';for(let i=0;i<100;i++){const x=(i*127)%worldW,y=FLOOR+7+(i*31)%82;ctx.fillRect(x,y,rand(6,24),1)}ctx.globalAlpha=1;
// black pines framing the arena
for(let i=0;i<24;i++){let x=i*86+23;let h=95+(i*43%98);ctx.fillStyle=i%2?'#0c191d':'#102024';ctx.beginPath();ctx.moveTo(x,FLOOR-h);ctx.lineTo(x-34,FLOOR);ctx.lineTo(x+35,FLOOR);ctx.fill();ctx.fillStyle='#80918a';ctx.globalAlpha=.35;ctx.beginPath();ctx.moveTo(x,FLOOR-h);ctx.lineTo(x-9,FLOOR-h*.48);ctx.lineTo(x+2,FLOOR-h*.55);ctx.fill();ctx.globalAlpha=1;}
// frozen runes / broken stones
for(let i=0;i<9;i++){let x=160+i*203;ctx.fillStyle='#253536';ctx.fillRect(x,FLOOR-38,10,38);ctx.fillRect(x-9,FLOOR-34,28,5);ctx.strokeStyle='#8cc6bd55';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+4,FLOOR-27);ctx.lineTo(x+7,FLOOR-19);ctx.lineTo(x+3,FLOOR-10);ctx.stroke();}}

