function drawFog(){const x0=camera-80,x1=camera+W+80;ctx.save();ctx.globalCompositeOperation='screen';for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(x0,FLOOR);for(let x=x0;x<=x1;x+=26){const y=FLOOR-8-i*8+Math.sin(x*.013+timer*(.25+i*.08)+i*2)*5;ctx.lineTo(x,y)}ctx.lineTo(x1,FLOOR+22);ctx.lineTo(x0,FLOOR+22);ctx.closePath();ctx.fillStyle=`rgba(176,198,191,${.032+i*.014})`;ctx.fill()}ctx.restore();}
function drawRunes(){ctx.save();ctx.translate(950,FLOOR-1);ctx.scale(1,.25);ctx.globalAlpha=.2+Math.sin(timer*1.7)*.06;ctx.strokeStyle='#8fd8cd';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,120,0,Math.PI*2);ctx.stroke();ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,88,0,Math.PI*2);ctx.stroke();for(let i=0;i<8;i++){const a=i/8*Math.PI*2;ctx.save();ctx.rotate(a);ctx.translate(0,-104);ctx.beginPath();ctx.moveTo(-4,-8);ctx.lineTo(3,-1);ctx.lineTo(-2,4);ctx.lineTo(4,11);ctx.stroke();ctx.restore()}ctx.restore();}
function drawBolts(){for(const b of bolts){const a=clamp(b.life/b.max,0,1);ctx.save();ctx.translate(b.x,FLOOR);ctx.globalAlpha=a;ctx.fillStyle='#9fe7e0';ctx.shadowColor='#82e8df';ctx.shadowBlur=18;ctx.beginPath();ctx.moveTo(0,4);ctx.lineTo(b.dir*18,-12);ctx.lineTo(b.dir*6,-38);ctx.lineTo(b.dir*24,-23);ctx.lineTo(b.dir*33,-3);ctx.closePath();ctx.fill();ctx.globalAlpha=a*.55;ctx.strokeStyle='#d4f6ee';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-3,26,Math.PI,0);ctx.stroke();ctx.restore()}}
function drawEmber(e){ctx.save();ctx.globalAlpha=clamp(e.life/e.max,0,1);ctx.fillStyle='#e9a35e';ctx.shadowColor='#f4a257';ctx.shadowBlur=9;ctx.beginPath();ctx.arc(e.x,e.y,e.size,0,Math.PI*2);ctx.fill();ctx.restore();}
function drawDamage(t){ctx.save();ctx.globalAlpha=clamp(t.life/t.max,0,1);ctx.textAlign='center';ctx.fillStyle=t.big?'#f6dda5':'#e7e3d6';ctx.font=`600 ${t.big?22:16}px Cinzel,serif`;ctx.shadowColor='#091012';ctx.shadowBlur=8;ctx.fillText(t.v,t.x,t.y);ctx.restore();}

